  "\"Show Labels\" is \"First Record Only\", so labels are drawn only in the first record unless a feature has Label visibility \"On\".": "قيمة الإعداد \"إظهار التسميات\" هي \"السجل الأول فقط\"، لذا يتم رسم التسميات في السجل الأول فقط ما لم تكن قيمة الإعداد \"رؤية التسمية\" لعنصر ما هي \"تشغيل\".",
  "\"Show Labels\" is \"Top Similarity Group Record\", so labels are drawn only for the features that setting selects, unless a feature has Label visibility \"On\".": "قيمة الإعداد \"إظهار التسميات\" هي \"السجل الأول في مجموعة التشابه\"، لذا يتم رسم التسميات للعناصر التي يحددها هذا الإعداد فقط، ما لم تكن قيمة الإعداد \"رؤية التسمية\" لعنصر ما هي \"تشغيل\".",
