  "A color rule would draw a Legend item that already exists in another color. Change the rule's Legend name or color, or rename that Legend item.": "ستؤدي إحدى قواعد الألوان إلى رسم إدخال في وسيلة الإيضاح موجود بالفعل بلون آخر. يُرجى تغيير الاسم في وسيلة الإيضاح أو اللون في تلك القاعدة، أو إعادة تسمية ذلك الإدخال.",
  "A comparison cannot connect a record to itself.": "لا يمكن أن تربط المقارنة سجلاً بنفسه.",
