  "A feature": "عنصر",
  "A feature edit does not identify a record of the current inputs. Generate again; if it continues, save a Session for investigation.": "لا يحدد أحد تعديلات العناصر أي سجل في المدخلات الحالية. يُرجى إعادة إنشاء المخطط، وإذا استمرت المشكلة، يُرجى حفظ جلسة لأغراض الفحص.",
  "A file of four or more columns is read as bedGraph: reference, 0-based start, end and value, each end greater than its start, and the rows of a reference in increasing order without overlaps. For samtools depth of several samples, keep the reference, position and one sample's column, or write the file with samtools depth -H.": "تتم قراءة الملف المكون من أربعة أعمدة أو أكثر بتنسيق bedGraph: التسلسل المرجعي، والبداية (تبدأ من 0)، والنهاية، والقيمة، على أن تكون كل نهاية أكبر من بدايتها، وأن تكون صفوف كل تسلسل مرجعي مرتبة تصاعدياً دون تداخل. وبالنسبة إلى مخرجات samtools depth لعدة عينات، يُرجى الاحتفاظ بعمود التسلسل المرجعي وعمود الموضع وعمود عينة واحدة، أو كتابة الملف باستخدام الأمر samtools depth -H.",
  "A genome diagram generator for microbes and organelles": "أداة لإنشاء مخططات الجينوم للكائنات الحية الدقيقة والعضيات",
  "A label blacklist is set, and a label whose text contains one of its keywords is not drawn.": "تم ضبط قائمة حظر التسميات، ولا يتم رسم أي تسمية يحتوي نصها على إحدى كلماتها المفتاحية.",
