  "A query holds a character that is neither a nucleotide nor an amino acid code. Give DNA, RNA or protein sequences in FASTA: letters, and * for a stop.": "يحتوي أحد تسلسلات query على حرف ليس رمز نيوكليوتيد ولا رمز حمض أميني. يُرجى توفير تسلسلات DNA أو RNA أو بروتين بصيغة FASTA: أحرف، والرمز * لكودون التوقف.",
  "A record of this FASTA file has no sequence. Give each FASTA record its sequence.": "لا يحتوي أحد سجلات ملف FASTA هذا على تسلسل. يُرجى توفير تسلسل لكل سجل FASTA.",
  "A record of this pair is drawn in several windows, and a BLAST TSV gives the coordinates of one drawn record. Set the pair to Run LOSAT.": "يتم رسم أحد سجلي هذا الزوج في عدة نوافذ، بينما يوفر ملف BLAST TSV إحداثيات سجل واحد مرسوم. يُرجى ضبط الزوج على \"تشغيل LOSAT\".",
  "A row length of {length} bp should fit (estimated from the drawn height).": "من المتوقع أن يتسع صف بطول {length} bp (وفق تقدير يستند إلى الارتفاع المرسوم).",
