  "A table row names another displayed record in this column. Swap the query and subject columns of the table, or assign the table to the pair it describes.": "يشير صف في الجدول إلى سجل معروض آخر في هذا العمود. يُرجى تبديل عمودي query و subject في الجدول، أو تعيين الجدول إلى الزوج الذي يصفه.",
  "A wrapped figure draws no comparisons. Remove the comparison inputs (BLAST, comparison pairs, LOSAT, Similarity groups), or turn Wrap Rows off.": "لا يرسم الشكل الذي يقسم السجلات على عدة صفوف أي مقارنات. يُرجى إزالة مدخلات المقارنة (BLAST، أزواج المقارنة، LOSAT، مجموعات التشابه)، أو إيقاف تشغيل الإعداد \"التفاف الصفوف\".",
  "A wrapped figure draws no comparisons. Remove the comparison inputs (BLAST, comparison pairs, LOSAT, Similarity groups).": "لا يرسم الشكل الذي يقسم السجلات على عدة صفوف أي مقارنات. يُرجى إزالة مدخلات المقارنة (BLAST، أزواج المقارنة، LOSAT، مجموعات التشابه).",
