  "A wrapped record cannot keep a sideways move (from Align at feature, Similarity groups, or a loaded Session). Click Reset record positions under Wrap Rows.": "لا يمكن للسجل الملتف الاحتفاظ بإزاحة جانبية (ناتجة عن الخيار \"محاذاة عند عنصر\" أو وضع \"مجموعات التشابه\" أو جلسة تم تحميلها). يمكنك النقر على الزر \"إعادة تعيين مواضع السجلات\" أسفل الإعداد \"التفاف الصفوف\".",
  "A wrapped record needs a Record Layout row of its own. Give each record its own row, or turn Wrap Rows off.": "يحتاج السجل الملتف إلى صف خاص به في القسم \"تخطيط السجلات\". يُرجى تخصيص صف لكل سجل، أو إيقاف تشغيل الإعداد \"التفاف الصفوف\".",
