  "Add within-record searches and group proteins, paralogs included, into similarity groups before blocks are built. Off by default: blocks are built from between-record hits without similarity groups.": "إضافة عمليات بحث داخل السجل وتجميع البروتينات، بما في ذلك paralog، في مجموعات تشابه قبل بناء الكتل. هذا الإعداد معطل افتراضياً: تُبنى الكتل من نتائج المطابقة بين السجلات دون مجموعات تشابه.",
  "Add {name}": "إضافة {name}",
  "Adding a Depth file, or a series while a Depth file is loaded, turns Show Depth on, and removing the last Depth file or its genome file turns Show Depth off; turning Show Depth off hides the drawn Depth track at once. A changed Legend title clears a Legend tab rename of the old title at once. The rest, and a Depth track from changed files, apply on Generate.": "تؤدي إضافة ملف عمق، أو إضافة سلسلة بيانات مع وجود ملف عمق محمل، إلى تشغيل الخيار \"إظهار العمق\"، وتؤدي إزالة آخر ملف عمق أو ملف الجينوم الخاص به إلى إيقاف الخيار \"إظهار العمق\"؛ ويؤدي إيقاف هذا الخيار إلى إخفاء مسار العمق المرسوم فوراً. ويؤدي تغيير عنوان وسيلة الإيضاح إلى مسح إعادة تسمية العنوان القديم التي أجريت في علامة التبويب \"وسيلة الإيضاح\" فوراً. أما بقية التغييرات، ومسار العمق الناتج عن تغيير الملفات، فيتم تطبيقها عند الإنشاء.",
