  "Additional visible gap ratio between row content bounds in multi-record canvas. 0 makes rows touch by content bounds. Default: 0.05 (vertical only).": "نسبة إضافية للفجوة المرئية بين حدود محتوى الصفوف على لوحة الرسم متعددة السجلات. تجعل القيمة 0 الصفوف متلامسة عند حدود المحتوى. الافتراضي: 0.05 (رأسي فقط).",
