  "Align applies resolved targets immediately; ambiguity opens review. Review alignment options… lets you inspect or change anchors, Skip, and direction before applying.": "تطبق عملية \"محاذاة\" الأهداف المحسوبة فوراً، ويؤدي الغموض إلى فتح المراجعة. ويتيح الزر \"مراجعة خيارات المحاذاة…\" فحص المراسي وخيار \"تخطي\" والاتجاه أو تغييرها قبل التطبيق.",
  "Align at feature": "محاذاة عند عنصر",
  "Align at feature cannot line up these records while Wrap Rows cuts a record into rows: it would move a cut record sideways, or line the others up with the feature of a cut record that it does not rotate. Only a complete circular record is aligned by rotation and can be wrapped. Turn Wrap Rows off, then use Align at feature.": "لا يمكن للخيار \"محاذاة عند عنصر\" محاذاة هذه السجلات ما دام الإعداد \"التفاف الصفوف\" يقسم السجل إلى صفوف: إذ سينقل سجلاً مقسوماً جانبياً، أو يحاذي بقية السجلات مع عنصر في سجل مقسوم لا يقوم بتدويره. السجل الدائري الكامل وحده هو الذي تتم محاذاته بالتدوير ويمكن التفافه. يُرجى إيقاف تشغيل الإعداد \"التفاف الصفوف\" ثم استخدام الخيار \"محاذاة عند عنصر\".",
  "Align at feature writes each record's start on its own File card, and these records share one File card (a file with several records). Click Generate Diagram, which gives each record its own File card, then use Align at feature again.": "يكتب الخيار \"محاذاة عند عنصر\" بداية كل سجل على بطاقة الملف الخاصة به، بينما تشترك هذه السجلات في بطاقة ملف واحدة (ملف يحتوي على عدة سجلات). يُرجى النقر على الزر \"إنشاء المخطط\" الذي يمنح كل سجل بطاقة ملف خاصة به، ثم استخدام الخيار \"محاذاة عند عنصر\" مرة أخرى.",
  "Align at feature…": "محاذاة عند عنصر…",
