  "Applies now, also over the queued palette.": "يسري الآن، وتكون له الأولوية أيضاً على ألوان لوحة الألوان الموجودة في قائمة الانتظار.",
  "Applies on Generate": "يسري عند الإنشاء",
  "Applies on Generate, except turning a GC content, GC skew or Depth row on or off, removing one, and Use custom stack, which apply at once. These still apply on Generate: turning on a row added since the last Generate, a row that was off when the Session was loaded, or a Depth row after a Depth file change; and Use custom stack after a Session load (except when turned off on a Linear Result drawn with it) or while the Region Annotation sets differ from those of the Result, with every track it would hide or show.": "يسري عند الإنشاء، باستثناء تشغيل صف محتوى GC أو صف GC skew أو صف العمق أو إيقافه، وإزالة أحد هذه الصفوف، والخيار \"استخدام مكدس مخصص\"، فهذه تسري فوراً. ويظل التطبيق عند الإنشاء في الحالات التالية: تشغيل صف تمت إضافته منذ آخر إنشاء، أو صف كان متوقفاً عند تحميل الجلسة، أو صف العمق بعد تغيير ملف العمق؛ والخيار \"استخدام مكدس مخصص\" بعد تحميل جلسة (إلا عند إيقافه في نتيجة مخطط خطي تم رسمها به) أو عندما تختلف مجموعات التعليقات التوضيحية للمناطق عن مجموعات النتيجة، مع كل مسار سيخفيه المكدس أو يظهره.",
  "Applies the live circular track arrangement used while Custom Track Slots is off. Custom Track Slots inherit this preset when enabled.": "يطبق الترتيب المباشر لمسارات المخطط الدائري المستخدم عند إيقاف الخيار \"خانات المسارات المخصصة\". وعند تمكين الخيار \"خانات المسارات المخصصة\" ترث الخانات هذا الإعداد المسبق.",
  "Applies to SVG and Interactive SVG exports, not to Generate.": "يسري على تصدير SVG و SVG التفاعلي، وليس على الإنشاء.",
  "Apply": "تطبيق",
