  "Auto (Default)": "تلقائي (افتراضي)",
  "Auto (by genome size)": "تلقائي (حسب حجم الجينوم)",
  "Auto ({count} parallel run)": "تلقائي ({count} عملية تشغيل متوازية)",
  "Auto ({count} parallel runs)": {"zero": "تلقائي ({count} عملية تشغيل متوازية)", "two": "تلقائي ({count} عملية تشغيل متوازية)", "few": "تلقائي ({count} عمليات تشغيل متوازية)", "many": "تلقائي ({count} عملية تشغيل متوازية)", "other": "تلقائي ({count} عملية تشغيل متوازية)"},
