  "Auto ({value})": "تلقائي ({value})",
  "Auto Reflow": "إعادة التوزيع التلقائية",
  "Auto Reflow failed. Current diagram is kept.": "فشلت إعادة التوزيع التلقائية. يتم الاحتفاظ بالمخطط الحالي.",
  "Auto embeds labels that fit and routes the rest externally. Embedded Only drops labels that need external placement. External Only keeps labels outside feature bodies.": "يؤدي الخيار \"تلقائي\" إلى تضمين التسميات التي تتسع وتوجيه الباقي إلى الخارج. ويستبعد الخيار \"مضمنة فقط\" التسميات التي تحتاج إلى موضع خارجي. ويبقي الخيار \"خارجية فقط\" التسميات خارج أجسام العناصر.",
  "Auto follows the track layout (Above or Features on axis: labels above; Below: labels below). Above Feature draws labels above features (and below negative-strand features when Separate Strands is on).": "يتبع الخيار \"تلقائي\" تخطيط المسارات (\"فوق\" أو \"العناصر على المحور\": التسميات فوق؛ \"تحت\": التسميات تحت). ويرسم الخيار \"فوق العنصر\" التسميات فوق العناصر (وتحت عناصر السلسلة العكسية عند تشغيل الإعداد \"فصل السلاسل\").",
  "Auto hides these fields throughout the diagram": "يؤدي الخيار \"تلقائي\" إلى إخفاء هذه الحقول في المخطط بأكمله",
  "Auto makes the CDSs that share a locus identifier one unit and every other CDS a unit of its own. CDS makes each CDS a unit. Locus makes each locus a unit and requires a locus identifier, such as /locus_tag, on every CDS.": "يجعل الخيار \"تلقائي\" عناصر CDS التي تشترك في معرّف موقع جيني وحدة واحدة، ويجعل كل عنصر CDS آخر وحدة مستقلة. يجعل الخيار \"CDS\" كل عنصر CDS وحدة. يجعل الخيار \"الموقع الجيني\" كل موقع جيني وحدة ويتطلب معرّف موقع جيني، مثل /locus_tag، في كل عنصر CDS.",
  "Auto runs threaded LOSAT when this browser supports it, and serial LOSAT otherwise. LOSATN task dc-megablast needs threaded LOSAT.": "يشغّل الخيار \"تلقائي\" أداة LOSAT بتنفيذ متعدد مؤشرات الترابط إذا كان هذا المتصفح يدعمه، وإلا فبتنفيذ متتابع. تتطلب مهمة LOSATN المسماة dc-megablast تشغيل LOSAT بتنفيذ متعدد مؤشرات الترابط.",
  "Auto shows these fields throughout the diagram": "يؤدي الخيار \"تلقائي\" إلى إظهار هذه الحقول في المخطط بأكمله",
  "Auto will hide these fields throughout the diagram on the next successful Generate": "سيؤدي الخيار \"تلقائي\" إلى إخفاء هذه الحقول في المخطط بأكمله عند الإنشاء الناجح التالي",
  "Auto will show these fields throughout the diagram on the next successful Generate": "سيؤدي الخيار \"تلقائي\" إلى إظهار هذه الحقول في المخطط بأكمله عند الإنشاء الناجح التالي",
