  "Bakta also sets the CDS default color to {color} and the Legend box size and font size to 12.": "كما يضبط الإعداد المسبق Bakta لون CDS الافتراضي على {color}، وحجم مربع وسيلة الإيضاح وحجم الخط على 12.",
