  "Bar (Simple)": "شريط (بسيط)",
  "Base colors for features, comparison tracks, and collinear blocks. The selected palette supplies unchanged colors; colors you edit override it; when you change the palette, a dialog asks whether to keep them.": "ألوان أساسية للعناصر ومسارات المقارنة وكتل Collinear. توفر لوحة الألوان المحددة الألوان غير المعدّلة، وتتجاوز الألوان المعدّلة ألوان اللوحة؛ وعند تغيير لوحة الألوان يسأل مربع حوار عن الاحتفاظ بالألوان المعدّلة.",
  "Base text shown in the diagram legend. Leave blank to use the auto label shown here; two-color tracks add (+) and (-).": "النص الأساسي الظاهر في وسيلة إيضاح المخطط. يمكنك ترك الحقل فارغاً لاستخدام التسمية التلقائية الظاهرة هنا؛ وتضيف المسارات ثنائية اللون (+) و(-).",
