  "Changing \"{setting}\" to \"{value}\" removes the lane for {count} features you placed manually.": {"zero": "يزيل تغيير الإعداد \"{setting}\" إلى القيمة \"{value}\" المسار الفرعي للعناصر الموضوعة يدوياً ({count}).", "two": "يزيل تغيير الإعداد \"{setting}\" إلى القيمة \"{value}\" المسار الفرعي للعناصر الموضوعة يدوياً ({count}).", "few": "يزيل تغيير الإعداد \"{setting}\" إلى القيمة \"{value}\" المسار الفرعي للعناصر الموضوعة يدوياً ({count}).", "many": "يزيل تغيير الإعداد \"{setting}\" إلى القيمة \"{value}\" المسار الفرعي للعناصر الموضوعة يدوياً ({count}).", "other": "يزيل تغيير الإعداد \"{setting}\" إلى القيمة \"{value}\" المسار الفرعي للعناصر الموضوعة يدوياً ({count})."},
