  "Choose a candidate or Skip for {count} records.": {"zero": "يُرجى اختيار مرشح أو الخيار \"تخطي\" لكل سجل من السجلات ({count}).", "two": "يُرجى اختيار مرشح أو الخيار \"تخطي\" لكل سجل من السجلات ({count}).", "few": "يُرجى اختيار مرشح أو الخيار \"تخطي\" لكل سجل من السجلات ({count}).", "many": "يُرجى اختيار مرشح أو الخيار \"تخطي\" لكل سجل من السجلات ({count}).", "other": "يُرجى اختيار مرشح أو الخيار \"تخطي\" لكل سجل من السجلات ({count})."},
