  "Choose a readable TrueType or OpenType font file ({trueType}, {openType}, {trueTypeCollection}, {openTypeCollection}) that names its font family.": "يُرجى اختيار ملف خط TrueType أو OpenType قابل للقراءة ({trueType}، {openType}، {trueTypeCollection}، {openTypeCollection}) يحدد اسم عائلة الخطوط الخاصة به.",
