  "Choose each feature type's rendering. Underlay removes it from feature lanes and labels, then highlights each feature's span across the full thickness of the feature track, behind foreground features.": "يمكن اختيار طريقة رسم كل نوع من أنواع العناصر. يزيل الخيار \"طبقة سفلية\" عناصر هذا النوع من المسارات الفرعية للعناصر ويزيل تسمياتها، ثم يميز امتداد كل عنصر بكامل سماكة مسار العناصر، خلف عناصر المقدمة.",
  "Choose file": "اختيار ملف",
