  "Choosing \"{setting}\" removes the lane for {count} features you placed manually.": {"zero": "يزيل اختيار الإعداد \"{setting}\" المسار الفرعي للعناصر الموضوعة يدوياً ({count}).", "two": "يزيل اختيار الإعداد \"{setting}\" المسار الفرعي للعناصر الموضوعة يدوياً ({count}).", "few": "يزيل اختيار الإعداد \"{setting}\" المسار الفرعي للعناصر الموضوعة يدوياً ({count}).", "many": "يزيل اختيار الإعداد \"{setting}\" المسار الفرعي للعناصر الموضوعة يدوياً ({count}).", "other": "يزيل اختيار الإعداد \"{setting}\" المسار الفرعي للعناصر الموضوعة يدوياً ({count})."},
