  "Custom Track Slots must be a list of rows.": "يجب أن تكون خانات المسارات المخصصة قائمة من الصفوف.",
  "Custom Track Slots need at least one enabled row.": "تتطلب خانات المسارات المخصصة صفاً ممكّناً واحداً على الأقل.",
  "Custom Track Slots no longer read this field. Use slot-level radius, width, inner_gap_px, outer_gap_px, side, and z fields.": "لم تعد خانات المسارات المخصصة تقرأ هذا الحقل. يُرجى استخدام حقول radius و width و inner_gap_px و outer_gap_px و side و z على مستوى الخانة.",
  "Custom position": "موضع مخصص",
  "Custom stack Depth rows control rendering. Disable the custom stack to change this simple control.": "تتحكم صفوف العمق في المكدس المخصص في الرسم. يمكنك تعطيل المكدس المخصص لتغيير أداة التحكم البسيطة هذه.",
  "Custom stack geometry is active. Use each Depth row width, or Reset to copy this value into the stack.": "أبعاد المكدس المخصص نشطة. يُرجى استخدام عرض كل صف عمق، أو النقر على الزر \"إعادة تعيين\" لنسخ هذه القيمة إلى المكدس.",
  "Custom stack geometry is active. Use the Dinucleotide content row radius, or Reset to copy this value into the stack.": "أبعاد المكدس المخصص نشطة. يمكنك استخدام نصف قطر الصف \"محتوى ثنائي النيوكليوتيد\"، أو استخدام الزر \"إعادة تعيين\" لنسخ هذه القيمة إلى المكدس.",
  "Custom stack geometry is active. Use the Dinucleotide content row width, or Reset to copy this value into the stack.": "أبعاد المكدس المخصص نشطة. يمكنك استخدام عرض الصف \"محتوى ثنائي النيوكليوتيد\"، أو استخدام الزر \"إعادة تعيين\" لنسخ هذه القيمة إلى المكدس.",
  "Custom stack geometry is active. Use the Dinucleotide skew row radius, or Reset to copy this value into the stack.": "أبعاد المكدس المخصص نشطة. يمكنك استخدام نصف قطر الصف \"skew ثنائي النيوكليوتيد\"، أو استخدام الزر \"إعادة تعيين\" لنسخ هذه القيمة إلى المكدس.",
  "Custom stack geometry is active. Use the Dinucleotide skew row width, or Reset to copy this value into the stack.": "أبعاد المكدس المخصص نشطة. يمكنك استخدام عرض الصف \"skew ثنائي النيوكليوتيد\"، أو استخدام الزر \"إعادة تعيين\" لنسخ هذه القيمة إلى المكدس.",
  "Custom stack geometry is active. Use the Features row width, or Reset to copy this value into the stack.": "أبعاد المكدس المخصص نشطة. يمكنك استخدام عرض الصف \"العناصر\"، أو استخدام الزر \"إعادة تعيين\" لنسخ هذه القيمة إلى المكدس.",
  "Custom stack is saved but inactive; generation uses the simple track controls.": "المكدس المخصص محفوظ، لكنه غير نشط؛ ويستخدم الإنشاء أدوات التحكم البسيطة في المسارات.",
