  "Display feature labels on the map. 'First Record Only' shows labels only for the first record. 'Top Similarity Group Record' requires LOSATP similarity-group or collinear mode.": "عرض تسميات العناصر على الخريطة. يعرض الخيار \"السجل الأول فقط\" التسميات للسجل الأول فقط، ويتطلب الخيار \"السجل الأول في مجموعة التشابه\" وضع \"مجموعات التشابه\" أو وضع \"كتل Collinear\" في LOSATP.",
