  "Drag a record, legend, title, or Linear scale to reposition": "سحب سجل أو وسيلة الإيضاح أو العنوان أو مقياس المخطط الخطي لنقله",
  "Drag along a record to select a region": "السحب على امتداد سجل لتحديد منطقة",
  "Drag to reorder, or press the Up or Down arrow": "السحب لإعادة الترتيب، أو الضغط على مفتاح السهم لأعلى أو لأسفل",
  "Drag to resize": "السحب لتغيير الحجم",
  "Draw a Linear map.": "رسم خريطة المخطط الخطي.",
  "Draw a smaller region, or turn off tracks or labels you do not need, then save again.": "يُرجى رسم منطقة أصغر، أو إيقاف تشغيل المسارات أو التسميات غير الضرورية، ثم الحفظ مرة أخرى.",
  "Draw all records one after another on one circle.": "رسم جميع السجلات واحداً تلو الآخر على دائرة واحدة.",
  "Draw all sequences at the same displayed length. Hides the length bar.": "رسم جميع التسلسلات بالطول المعروض نفسه. ويؤدي ذلك إلى إخفاء شريط الطول.",
  "Draw each record over rows of this length. Leave the length empty for Auto, which chooses it from the longest record.": "رسم كل سجل على صفوف بهذا الطول. يمكنك ترك حقل الطول فارغاً لاستخدام \"تلقائي\"، الذي يختاره بحسب أطول سجل.",
  "Draw one circular pairwise comparison ring per uploaded BLAST outfmt 6/7 file or browser LOSATN/TLOSATX comparison sequence file (FASTA, GenBank, or DDBJ). Reverse BLAST coordinates are shown as reverse hits, not origin-spanning hits.": "رسم حلقة مقارنة زوجية واحدة في المخطط الدائري لكل ملف BLAST outfmt 6/7 محمّل أو لكل ملف تسلسل مقارنة (FASTA أو GenBank أو DDBJ) تعالجه LOSATN/TLOSATX في المتصفح. تُعرض إحداثيات BLAST العكسية كنتائج مطابقة عكسية، وليس كنتائج مطابقة تمتد عبر نقطة الأصل.",
  "Draw records": "رسم السجلات",
  "Draw the comparison rings. Generate runs their comparisons only while this is on.": "رسم حلقات المقارنة. لا يتم تشغيل مقارناتها عند الإنشاء إلا أثناء تشغيل هذا الخيار.",
  "Draw this record": "رسم هذا السجل",
  "Draw {set} again": "رسم المجموعة {set} مرة أخرى",
  "Drawing": "الرسم",
  "Drawing menu for {name}": "قائمة الرسم: {name}",
  "Drawing name": "اسم الرسم",
  "Drawings": "الرسومات",
  "Draws each label that the label priority names from the gene qualifier in italics, also after its text is edited. Other labels stay upright.": "يتم رسم كل تسمية بخط مائل إذا أخذت نصها من حقل qualifier المسمى gene وفق أولوية qualifier، حتى بعد تحرير هذا النص. وتبقى التسميات الأخرى غير مائلة.",
  "Duplicate": "تكرار",
  "Duplicate drawing": "تكرار الرسم",
  "Duplicate set": "تكرار المجموعة",
  "Duplicate track": "تكرار المسار",
  "Duplicate track {id}": "تكرار المسار {id}",
  "Duplicating this row would make the custom stack invalid": "سيؤدي تكرار هذا الصف إلى جعل المكدس المخصص غير صالح",
  "E-value": "E-value",
  "E-value ≤ {value}": "قيمة E-value: بحد أقصى {value}",
  "Each file becomes one row of the new drawing. Untick a window to leave it out.": "يصبح كل ملف صفاً واحداً في الرسم الجديد. يمكنك إلغاء تحديد نافذة لاستبعادها.",
  "Each file is used for every record.": "يُستخدم كل ملف لكل سجل.",
  "Each selected pair must join two different available records on adjacent rows, and appear once.": "يجب أن يربط كل زوج محدد بين سجلين مختلفين متوفرين في صفين متجاورين، وأن يظهر مرة واحدة فقط.",
  "Each track counts the features one query finds in each window of every record, as a heatmap or a histogram. The query is a feature type (* for every type), with an optional qualifier, value regex and length range.": "يحسب كل مسار العناصر التي يعثر عليها استعلام واحد في كل نافذة من كل سجل، في شكل خريطة حرارية أو مدرج تكراري. يتكون الاستعلام من نوع العنصر (* لكل الأنواع)، مع qualifier وتعبير عادي للقيمة ومدى للطول، وكلها اختيارية.",
  "Each wrapped row draws a ruler on its axis. Set Scale Style to Ruler (Ticks), or turn Wrap Rows off.": "يرسم كل صف ملتف مسطرة على محوره. يُرجى ضبط الإعداد \"طراز المقياس\" على \"مسطرة (علامات التجزئة)\"، أو إيقاف تشغيل الإعداد \"التفاف الصفوف\".",
  "Edge kind": "نوع الحافة",
  "Edit": "تحرير",
  "Edit Species / Strain…": "تحرير النوع / السلالة…",
  "Edit feature visibility rule": "تحرير قاعدة رؤية العناصر",
  "Edit label text": "تحرير نص التسمية",
  "Edit pattern": "تحرير النمط",
  "Edit record definition": "تحرير تعريف السجل",
  "Edit setting": "تحرير الإعداد",
  "Edit specific color rule": "تحرير قاعدة ألوان خاصة",
  "Edit the explicit circular stack. Opening or closing this panel does not enable or alter the stack. Rows above Axis render outside and rows below Axis render inside.": "تحرير مكدس مسارات المخطط الدائري الصريح. لا يؤدي فتح هذه اللوحة أو إغلاقها إلى تمكين المكدس أو تغييره. يتم رسم الصفوف التي فوق الصف \"المحور\" في الخارج، والصفوف التي تحته في الداخل.",
  "Edit the explicit linear track stack. Opening or closing this panel does not enable or alter the stack. Arrows reorder within the current side; Row actions move rows across the boundary.": "تحرير مكدس مسارات المخطط الخطي الصريح. لا يؤدي فتح هذه اللوحة أو إغلاقها إلى تمكين المكدس أو تغييره. تعيد الأسهم الترتيب داخل الجانب الحالي؛ وتنقل خيارات القائمة \"إجراءات الصف\" الصفوف عبر الحد الفاصل.",
  "Edit this record in its File card in the sidebar.": "يمكنك تحرير هذا السجل في بطاقة الملف الخاصة به في الشريط الجانبي.",
