  "Feature types drawn as Underlay (repeat_region by default) need exactly one enabled Features row. Keep one Features row enabled, or set those types to Arrow or Rectangle in Feature Types.": "تتطلب أنواع العناصر المرسومة بوصفها \"طبقة سفلية\" (repeat_region افتراضياً) صف عناصر ممكّناً واحداً بالضبط. يُرجى إبقاء صف عناصر واحد ممكّناً، أو ضبط هذه الأنواع على \"سهم\" أو \"مستطيل\" في الحقل \"أنواع العناصر\".",
