  "Fix before Generate": "يجب الإصلاح قبل الإنشاء",
  "Fix the identity color scale so figures with different thresholds share colors and Legend labels. Leave the minimum blank to color from the minimum identity to 100%.": "تثبيت مقياس ألوان التطابق بحيث تشترك الأشكال ذات العتبات المختلفة في الألوان وتسميات وسيلة الإيضاح. يمكنك ترك الحد الأدنى فارغاً لتلوين المدى من الحد الأدنى للتطابق إلى 100%.",
