  "Font": "الخط",
  "Font size": "حجم الخط",
  "Font size for GC content percent tick labels. Leave blank for auto.": "حجم الخط لتسميات علامات التجزئة للنسبة المئوية لمحتوى GC. يؤدي ترك الحقل فارغاً إلى استخدام القيمة التلقائية.",
  "Font size for circular tick labels. Leave blank to use the default size.": "حجم الخط لتسميات علامات التجزئة في المخطط الدائري. يؤدي ترك الحقل فارغاً إلى استخدام الحجم الافتراضي.",
  "Font size for feature labels.": "حجم الخط لتسميات العناصر.",
  "Font size for record-label text (species/strain in circular; organism/replicon/accession/length stack in linear).": "حجم الخط لنص تسميات السجلات (النوع/السلالة في المخطط الدائري؛ وأسطر الكائن الحي/replicon/رقم الانضمام/الطول المكدسة في المخطط الخطي).",
  "Font size for ruler tick labels, including rulers drawn on record axes.": "حجم الخط لتسميات علامات التجزئة على المسطرة، بما في ذلك المساطر المرسومة على محاور السجلات.",
  "Font size for the circular shared plot title. Only used when the title position is Top or Bottom.": "حجم الخط لعنوان المخطط الدائري المشترك. يُستخدم فقط عندما يكون موضع العنوان هو الخيار \"أعلى\" أو الخيار \"أسفل\".",
  "Font size for the legend text.": "حجم الخط لنص وسيلة الإيضاح.",
  "Font size for the linear plot title.": "حجم الخط لعنوان المخطط الخطي.",
  "Font size for the simple bar scale label.": "حجم الخط لتسمية شريط المقياس البسيط.",
  "Font size for this track's depth tick labels. Leave blank for auto.": "حجم الخط لتسميات علامات التجزئة في مسار العمق هذا. يمكنك ترك الحقل فارغاً لاستخدام القيمة التلقائية.",
  "Font {family} could not be prepared for the PDF. Its text is drawn in {substitute}.": "تعذر تجهيز الخط {family} لملف PDF. يتم رسم نصه بالخط {substitute}.",
  "Font {family} is not embedded in the PDF: its license (OS/2 fsType) does not allow embedding. Its text is drawn in {substitute}.": "لا يتم تضمين الخط {family} في ملف PDF: ترخيصه (OS/2 fsType) لا يسمح بالتضمين. يتم رسم نصه بالخط {substitute}.",
  "Font {family} is not embedded: its license (OS/2 fsType) does not allow embedding. The SVG shows it only where {family} is installed.": "الخط {family} غير مضمن: لا يسمح ترخيصه (OS/2 fsType) بتضمينه. لا يظهر هذا الخط في ملف SVG إلا حيث يكون الخط {family} مثبتاً.",
  "Fonts loaded in this page could not be prepared again for drawing. Load them again in Font, or choose another font.": "تعذرت إعادة تجهيز الخطوط التي تم تحميلها في هذه الصفحة للرسم. يُرجى تحميلها مرة أخرى في القسم \"الخط\"، أو اختيار خط آخر.",
  "For Extend to, select an eligible enabled slot other than the anchor, or None.": "في الحقل \"التمديد حتى\"، يُرجى تحديد خانة ممكّنة مؤهلة غير المرساة، أو اختيار الخيار \"بلا\".",
