  "Head length divided by the full rendered feature thickness. Leave blank for Auto. Auto starts from the mode-specific default and lengthens the head as the shaft narrows.": "طول الرأس مقسوماً على السماكة الكاملة المرسومة للعنصر. يمكن ترك الحقل فارغاً لاستخدام \"تلقائي\": يبدأ طول الرأس عندئذ من القيمة الافتراضية الخاصة بوضع المخطط ويزداد كلما ضاق جسم السهم.",
