  "It matches the current settings.": "تطابق هذه النتيجة الإعدادات الحالية.",
  "It repeats a group, as in {example}, which can make the page stop responding.": "يتضمن مجموعة مكررة، كما في {example}، مما قد يتسبب في توقف الصفحة عن الاستجابة.",
  "Italic gene names": "أسماء الجينات بخط مائل",
  "Its edits and Result are removed": "تتم إزالة تعديلاته ونتيجته",
