  "Its style applies when the line is shown.": "يسري هذا الطراز عند إظهار السطر.",
  "Its text is set in {names}, which are not part of gbdraw and are not loaded in this page.": {"zero": "يستخدم نص هذه الجلسة الخطوط {names}، وهي ليست جزءاً من gbdraw وغير محملة في هذه الصفحة.", "two": "يستخدم نص هذه الجلسة الخطين {names}، وهما ليسا جزءاً من gbdraw وغير محملين في هذه الصفحة.", "few": "يستخدم نص هذه الجلسة الخطوط {names}، وهي ليست جزءاً من gbdraw وغير محملة في هذه الصفحة.", "many": "يستخدم نص هذه الجلسة الخطوط {names}، وهي ليست جزءاً من gbdraw وغير محملة في هذه الصفحة.", "other": "يستخدم نص هذه الجلسة الخطوط {names}، وهي ليست جزءاً من gbdraw وغير محملة في هذه الصفحة."},
  "Its text is set in {names}, which is not part of gbdraw and is not loaded in this page.": "يستخدم نص هذه الجلسة الخط {names}، وهو ليس جزءاً من gbdraw وغير محمل في هذه الصفحة.",
