  "Keep these choices and retry Apply below, or edit the choices before applying.": "يمكن الاحتفاظ بهذه الاختيارات وإعادة محاولة التطبيق بالنقر على الزر \"تطبيق\" أدناه، أو تحرير الاختيارات قبل التطبيق.",
  "Keep this drawing's settings and edits": "الاحتفاظ بإعدادات هذا الرسم وتعديلاته",
  "Keep window {record} {span}": "الاحتفاظ بالنافذة {record} {span}",
  "Keep your {count} changed color from the \"{palette}\" palette ({keys})?": "الاحتفاظ باللون المعدّل ({count}) من لوحة الألوان \"{palette}\" ({keys})؟",
  "Keep your {count} changed colors from the \"{palette}\" palette ({keys})?": {"zero": "الاحتفاظ بالألوان المعدّلة ({count}) من لوحة الألوان \"{palette}\" ({keys})؟", "two": "الاحتفاظ بالألوان المعدّلة ({count}) من لوحة الألوان \"{palette}\" ({keys})؟", "few": "الاحتفاظ بالألوان المعدّلة ({count}) من لوحة الألوان \"{palette}\" ({keys})؟", "many": "الاحتفاظ بالألوان المعدّلة ({count}) من لوحة الألوان \"{palette}\" ({keys})؟", "other": "الاحتفاظ بالألوان المعدّلة ({count}) من لوحة الألوان \"{palette}\" ({keys})؟"},
  "Kind": "النوع",
