  "Label fewer features: Blacklist or Whitelist under LABEL FILTERING.": "إظهار تسميات لعدد أقل من العناصر: استخدام الخيار \"قائمة الحظر\" أو الخيار \"قائمة السماح\" ضمن القسم \"تصفية التسميات\".",
