  "Labels are not drawn for features drawn as \"Underlay\".": "لا يتم رسم التسميات للعناصر المرسومة بوصفها \"طبقة سفلية\".",
  "Labels are not drawn on {type} features, because Feature Types draws them as Underlay.": "لا يتم رسم التسميات على عناصر {type}، لأن طريقة رسم هذه العناصر في الحقل \"أنواع العناصر\" هي \"طبقة سفلية\".",
  "Labels are set to \"None\" (\"Show Labels\" or \"Label Mode\"), so only a feature with Label visibility \"On\" has one.": "تم ضبط التسميات على \"بلا\" (في الإعداد \"إظهار التسميات\" أو الإعداد \"وضع التسميات\")، لذا لا تظهر تسمية إلا للعنصر الذي تكون قيمة الإعداد \"رؤية التسمية\" له هي \"تشغيل\".",
  "Labels cover the definition text ({count}).": "تغطي التسميات نص التعريف ({count}).",
  "Labels do not fit": "لا تتسع التسميات",
