  "Large tick interval in x coverage units. Leave blank for min/max ticks.": "الفاصل بين علامات التجزئة الكبيرة بوحدات التغطية x. يمكنك ترك الحقل فارغاً لاستخدام علامتي الحد الأدنى والحد الأقصى.",
  "Larger than the requested {size} after moves of the Legend, title, or scale, which the fit does not include.": "أكبر من الحجم المطلوب ({size}) بعد نقل وسيلة الإيضاح أو العنوان أو المقياس، وهو ما لا تشمله ملاءمة الشكل.",
  "Larger than the requested {size}.": "أكبر من الحجم المطلوب ({size}).",
  "Larger than the requested {size}: the edit could not be fitted (see the note above the preview).": "أكبر من الحجم المطلوب ({size}): تعذرت ملاءمة التعديل مع الحجم المطلوب (يُرجى الرجوع إلى الملاحظة أعلى المعاينة).",
