  "Legend: entries {items} had a color the app does not accept and were dropped.": {"zero": "وسيلة الإيضاح: الإدخالات {items} تحتوي على ألوان لا يقبلها التطبيق وتمت إزالة تلك الإدخالات.", "two": "وسيلة الإيضاح: الإدخالان {items} يحتويان على ألوان لا يقبلها التطبيق وتمت إزالتهما.", "few": "وسيلة الإيضاح: الإدخالات {items} تحتوي على ألوان لا يقبلها التطبيق وتمت إزالة تلك الإدخالات.", "many": "وسيلة الإيضاح: الإدخالات {items} تحتوي على ألوان لا يقبلها التطبيق وتمت إزالة تلك الإدخالات.", "other": "وسيلة الإيضاح: الإدخالات {items} تحتوي على ألوان لا يقبلها التطبيق وتمت إزالة تلك الإدخالات."},
  "Legend: entries {items} repeat an earlier entry of their list and were dropped.": {"zero": "وسيلة الإيضاح: الإدخالات {items} تكرر إدخالات سابقة في قائمتها وتمت إزالة الإدخالات المكررة.", "two": "وسيلة الإيضاح: الإدخالان {items} يكرران إدخالات سابقة في قائمتهما وتمت إزالتهما.", "few": "وسيلة الإيضاح: الإدخالات {items} تكرر إدخالات سابقة في قائمتها وتمت إزالة الإدخالات المكررة.", "many": "وسيلة الإيضاح: الإدخالات {items} تكرر إدخالات سابقة في قائمتها وتمت إزالة الإدخالات المكررة.", "other": "وسيلة الإيضاح: الإدخالات {items} تكرر إدخالات سابقة في قائمتها وتمت إزالة الإدخالات المكررة."},
  "Legend: entry {items} had a color the app does not accept and was dropped.": "وسيلة الإيضاح: الإدخال {items} يحتوي على لون لا يقبله التطبيق وتمت إزالة ذلك الإدخال.",
  "Legend: entry {items} repeats an earlier entry of its list and was dropped.": "وسيلة الإيضاح: الإدخال {items} يكرر إدخالاً سابقاً في قائمته وتمت إزالة الإدخال المكرر.",
  "Legend: the color edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "وسيلة الإيضاح: تعديل اللون المحفوظ باسم \"{label}\" ({path}) ينتقل إلى الصف \"{used}\" الذي له تعديل خاص به؛ يتم استخدام التعديل الخاص بالصف وتمت إزالة التعديل المنقول.",
  "Legend: the color edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "وسيلة الإيضاح: تعديل اللون المحفوظ باسم \"{label}\" ({path}) يخص الصف \"{used}\" الذي يخصه أيضاً تعديل لاحق؛ يتم استخدام التعديل اللاحق وتمت إزالة التعديل الأسبق.",
  "Legend: the entry stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an entry of its own; that entry is used and this one was dropped.": "وسيلة الإيضاح: الإدخال المحفوظ باسم \"{label}\" ({path}) ينتقل إلى الصف \"{used}\" الذي له إدخال خاص به؛ يتم استخدام الإدخال الخاص بالصف وتمت إزالة الإدخال المنقول.",
  "Legend: the entry stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "وسيلة الإيضاح: الإدخال المحفوظ باسم \"{label}\" ({path}) يخص الصف \"{used}\" الذي يخصه أيضاً تعديل لاحق؛ يتم استخدام التعديل اللاحق وتمت إزالة ذلك الإدخال.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; it is not used.": "وسيلة الإيضاح: الموضع \"{stored}\" ({path}) ليس من المواضع المتاحة في وضع المخطط الخاص بها؛ لذا لا يتم استخدامه.",
  "Legend: the position \"{stored}\" ({path}) is not one of its mode's positions; {used} is used.": "وسيلة الإيضاح: الموضع \"{stored}\" ({path}) ليس من المواضع المتاحة في وضع المخطط الخاص بها؛ يتم استخدام {used}.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) moves to the row \"{used}\", which has an edit of its own; that edit is used and this one was dropped.": "وسيلة الإيضاح: تعديل الحد المحفوظ باسم \"{label}\" ({path}) ينتقل إلى الصف \"{used}\" الذي له تعديل خاص به؛ يتم استخدام التعديل الخاص بالصف وتمت إزالة التعديل المنقول.",
  "Legend: the stroke edit stored under \"{label}\" ({path}) sets the row \"{used}\", which a later edit also sets; the later edit is used and this one was dropped.": "وسيلة الإيضاح: تعديل الحد المحفوظ باسم \"{label}\" ({path}) يخص الصف \"{used}\" الذي يخصه أيضاً تعديل لاحق؛ يتم استخدام التعديل اللاحق وتمت إزالة التعديل الأسبق.",
