  "Linear vertical spacing after the track, in pixels (px optional; nonnegative). Leave blank for the automatic spacing.": "التباعد الرأسي في المخطط الخطي بعد المسار، بالبكسل (الوحدة px اختيارية؛ قيمة غير سالبة). يمكنك ترك الحقل فارغاً لاستخدام التباعد التلقائي.",
  "Link Linear scale and ruler label font sizes": "ربط أحجام خطوط تسميات مقياس المخطط الخطي والمسطرة",
  "Link Scale and Ruler Label Font Sizes": "ربط أحجام خطوط تسميات المقياس والمسطرة",
  "List all 12 standard BLAST outfmt 6 fields in the \"{header}\" line, or remove the line so that the first 12 columns are read in the standard order.": "يُرجى سرد جميع حقول BLAST outfmt 6 القياسية البالغ عددها 12 في السطر \"{header}\"، أو إزالة السطر لتتم قراءة أول 12 عموداً بالترتيب القياسي.",
  "Live edit applying: geometry is being updated. Direct edits already applied are kept.": "جارٍ تطبيق التحرير المباشر: يجري تحديث الأبعاد. يتم الاحتفاظ بالتعديلات المباشرة التي تم تطبيقها بالفعل.",
  "Live edit failed: direct edits already applied are kept; geometry may still need updating.": "فشل التحرير المباشر: يتم الاحتفاظ بالتعديلات المباشرة التي تم تطبيقها بالفعل؛ وقد تحتاج الأبعاد إلى تحديث.",
  "Live edit. Showing a track applies on Generate if the Result did not draw it when its Session was loaded; after a Depth file or series change, or a change of the records the Depth files map to; for a custom stack row added since the last Generate or a stack the last Generate could not build; and, with a Circular custom track stack or Circular track widths or radii, when Hide GC Content or Hide GC Skew is turned off.": "تحرير مباشر. يسري إظهار المسار عند الإنشاء إذا لم تكن النتيجة قد رسمته عند تحميل جلستها؛ وبعد تغيير ملف العمق أو سلسلة البيانات، أو تغيير السجلات المرتبطة بملفات العمق؛ وفي صف مكدس مخصص تمت إضافته منذ آخر إنشاء أو مكدس تعذر على آخر إنشاء بناؤه؛ وعند إيقاف الخيار \"إخفاء محتوى GC\" أو \"إخفاء GC skew\" مع مكدس مسارات مخصص في المخطط الدائري أو مع عرض المسارات أو أنصاف أقطارها في المخطط الدائري.",
  "Live edit: feature color, label text, and visibility update the current Result; geometry may rerender automatically.": "تحرير مباشر: يؤدي تغيير لون العنصر ونص التسمية والرؤية إلى تحديث النتيجة الحالية؛ وقد تؤدي تغييرات الأبعاد إلى إعادة الرسم تلقائياً.",
  "Live edit: legend text, order, stroke, and removal update the current Result.": "تحرير مباشر: يتم تحديث النتيجة الحالية عند تغيير نص إدخالات وسيلة الإيضاح أو ترتيبها أو حدودها أو إزالتها.",
  "Live edit: the padding updates the current Result.": "تحرير مباشر: يؤدي تغيير الهامش إلى تحديث النتيجة الحالية.",
  "Live edit; the position applies on Generate after the Multi-Record Canvas change.": "تحرير مباشر؛ يسري الموضع عند الإنشاء بعد تغيير الإعداد \"لوحة رسم متعددة السجلات\".",
  "Live edit; the position applies on Generate after the One circle change.": "تحرير مباشر؛ يسري الموضع عند الإنشاء بعد تغيير الإعداد \"دائرة واحدة\".",
