  "Load with {substitutes}: the Session opens and its text is drawn in {substitutes}, the nearest available fonts.": {"zero": "تحميل باستخدام {substitutes}: يتم فتح الجلسة ورسم نصها بالخطوط {substitutes}، وهي أقرب الخطوط المتوفرة.", "two": "تحميل باستخدام {substitutes}: يتم فتح الجلسة ورسم نصها بالخطين {substitutes}، وهما أقرب خطين متوفرين.", "few": "تحميل باستخدام {substitutes}: يتم فتح الجلسة ورسم نصها بالخطوط {substitutes}، وهي أقرب الخطوط المتوفرة.", "many": "تحميل باستخدام {substitutes}: يتم فتح الجلسة ورسم نصها بالخطوط {substitutes}، وهي أقرب الخطوط المتوفرة.", "other": "تحميل باستخدام {substitutes}: يتم فتح الجلسة ورسم نصها بالخطوط {substitutes}، وهي أقرب الخطوط المتوفرة."},
