  "Make the figure larger: Figure height about {height} (Figure size in Layout).": "تكبير الشكل: ضبط الحقل \"ارتفاع الشكل\" على {height} تقريباً (الإعداد \"حجم الشكل\" في القسم \"التخطيط\").",
  "Make the figure larger: Figure width about {width} (Figure size in Layout).": "تكبير الشكل: ضبط الحقل \"عرض الشكل\" على {width} تقريباً (الإعداد \"حجم الشكل\" في القسم \"التخطيط\").",
  "Make the figure larger: Figure width about {width}, Figure height about {height} (Figure size in Layout).": "تكبير الشكل: ضبط الحقل \"عرض الشكل\" على {width} تقريباً، والحقل \"ارتفاع الشكل\" على {height} تقريباً (الإعداد \"حجم الشكل\" في القسم \"التخطيط\").",
  "Make the figure larger: increase Figure height (Figure size in Layout).": "تكبير الشكل: زيادة قيمة الحقل \"ارتفاع الشكل\" (الإعداد \"حجم الشكل\" في القسم \"التخطيط\").",
  "Make the figure larger: increase Figure width (Figure size in Layout).": "تكبير الشكل: زيادة قيمة الحقل \"عرض الشكل\" (الإعداد \"حجم الشكل\" في القسم \"التخطيط\").",
  "Make the figure larger: increase Figure width and Figure height (Figure size in Layout).": "تكبير الشكل: زيادة قيمة الحقل \"عرض الشكل\" وقيمة الحقل \"ارتفاع الشكل\" (الإعداد \"حجم الشكل\" في القسم \"التخطيط\").",
  "Manual order and row assignment for multi-record canvas. Use Up/Down for left-to-right order within each row.": "الترتيب اليدوي وتعيين الصفوف للوحة الرسم متعددة السجلات. يمكنك استخدام الزرين \"لأعلى\" و\"لأسفل\" لضبط الترتيب من اليسار إلى اليمين داخل كل صف.",
  "Manual scale interval for circular mode (in bp; must be > 0). Overrides automatic calculation.": "فاصل المقياس اليدوي لوضع المخطط الدائري (بوحدة bp؛ يجب أن يكون أكبر من 0). يتجاوز الحساب التلقائي.",
  "Manual tick interval for Ruler scale style in bp (must be > 0). Leave blank to calculate automatically.": "الفاصل اليدوي بين علامات التجزئة في طراز المقياس \"مسطرة\" بوحدة bp (يجب أن يكون أكبر من 0). يؤدي ترك الحقل فارغاً إلى حساب الفاصل تلقائياً.",
  "Marks": "العلامات",
  "Match depth references to the selected record.": "يُرجى مطابقة أسماء التسلسلات المرجعية في ملف TSV للعمق مع السجل المحدد.",
