  "Max hits per protein for groups": "الحد الأقصى لنتائج المطابقة لكل بروتين في المجموعات",
  "Max target seqs": "الحد الأقصى للتسلسلات الهدف",
  "Max unit gap": "الحد الأقصى للفجوة بالوحدات",
  "Maximum GC percentage for percent-mode clipping and axis scaling.": "الحد الأقصى لنسبة GC في وضع النسبة المئوية لتقييد القيم وتحديد مقياس المحور.",
  "Maximum depth for clipping and normalization. Leave blank for auto.": "الحد الأقصى للعمق لأغراض تقييد القيم والتسوية. يمكنك ترك الحقل فارغاً لاستخدام القيمة التلقائية.",
  "Maximum distinct subject proteins, not counting the protein itself, kept per query protein in each directed record-pair search to construct Similarity groups and Collinear blocks after result filtering. Leave blank to keep all hits passing the result filters. This does not limit raw LOSATP candidates or Pairwise display matches.": "الحد الأقصى لعدد بروتينات subject المتمايزة، دون احتساب البروتين نفسه، المحتفظ بها لكل بروتين query في كل بحث موجه بين زوج من السجلات لبناء مجموعات التشابه وكتل Collinear بعد تصفية النتائج. يمكنك ترك الحقل فارغاً للاحتفاظ بجميع نتائج المطابقة التي تجتاز عوامل تصفية النتائج. لا يحد هذا من النتائج المرشحة الخام في LOSATP ولا من تطابقات العرض الزوجي.",
  "Maximum filtered matches displayed per query protein in Pairwise mode. This does not limit LOSATP candidates or Similarity/Collinear member evidence.": "الحد الأقصى لعدد التطابقات المصفّاة المعروضة لكل بروتين query في وضع \"التطابقات الزوجية\". لا يحد هذا من النتائج المرشحة في LOSATP ولا من أدلة الأعضاء في مجموعات التشابه وكتل Collinear.",
  "Maximum number of units (loci, or CDSs without a locus identifier; see Unit mode) between neighboring anchors of one block, on both records. 0 joins adjacent units only. With Diagonal drift 0, a gap is bridged only when both records skip the same number of units.": "الحد الأقصى لعدد الوحدات (المواقع الجينية، أو عناصر CDS التي لا تحمل معرّف موقع جيني؛ يُرجى الرجوع إلى الإعداد \"وضع الوحدة\") بين مرساتين متجاورتين في كتلة واحدة، في كلا السجلين. تؤدي القيمة 0 إلى ربط الوحدات المتجاورة فقط. وعند ضبط الإعداد \"الانجراف القطري\" على 0، لا يتم سد الفجوة إلا إذا تخطى السجلان العدد نفسه من الوحدات.",
  "Members": "الأعضاء",
