  "Minimum label-to-label vertical spacing for circular layouts in px.": "الحد الأدنى للتباعد الرأسي بين تسمية وأخرى في تخطيطات المخطط الدائري بوحدة px.",
  "Minimum reserved height for the measured feature band, in pixels (px optional; positive). The actual reservation is max(measured, configured); this does not change feature glyph thickness, which is controlled by Feature Height ({option}). Auto values vary by record.": "الحد الأدنى للارتفاع المحجوز لنطاق العناصر المقيس، بالبكسل (الوحدة px اختيارية؛ قيمة موجبة). المساحة المحجوزة الفعلية هي الأكبر بين القيمة المقيسة والقيمة المضبوطة؛ ولا يغير هذا سماكة شكل العنصر، التي يتحكم فيها الحقل \"ارتفاع العنصر\" ({option}). وتختلف القيم التلقائية من سجل إلى آخر.",
