  "Multi-Record Canvas uses a grid. Turn it off to select one record.": "يستخدم الخيار \"لوحة رسم متعددة السجلات\" شبكة. يمكنك إيقاف تشغيله لتحديد سجل واحد.",
  "Name": "الاسم",
  "Name / Species": "الاسم / النوع",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. Leave blank for the default name: Depth, or Depth N when there are several series.": "اسم سلسلة بيانات العمق التي يرسمها هذا الصف. تؤدي الكتابة إلى إعادة تسمية السلسلة في كل مكان: بطاقة السلسلة وكل صف يرسمها ووسيلة الإيضاح. يمكنك ترك الحقل فارغاً لاستخدام الاسم الافتراضي: Depth، أو Depth N عند وجود عدة سلاسل بيانات.",
  "Name of the Depth series this row draws. Typing renames the series everywhere: its series card, every row that draws it, and the legend. The legend lists series in custom-stack order and omits series that no enabled row draws. Leave blank for the default name: Depth, or Depth N when there are several series.": "اسم سلسلة بيانات العمق التي يرسمها هذا الصف. تؤدي الكتابة إلى إعادة تسمية السلسلة في كل مكان: بطاقة السلسلة وكل صف يرسمها ووسيلة الإيضاح. تسرد وسيلة الإيضاح سلاسل البيانات بترتيب المكدس المخصص وتستبعد سلاسل البيانات التي لا يرسمها أي صف ممكّن. يمكنك ترك الحقل فارغاً لاستخدام الاسم الافتراضي: Depth، أو Depth N عند وجود عدة سلاسل بيانات.",
  "Name of this Depth series in the legend. The legend label field of every Depth row that draws this series edits the same name. Leave blank for the default name: Depth, or Depth N when there are several series.": "اسم سلسلة بيانات العمق هذه في وسيلة الإيضاح. يعدل حقل تسمية وسيلة الإيضاح في كل صف عمق يرسم هذه السلسلة الاسم نفسه. يمكنك ترك الحقل فارغاً لاستخدام الاسم الافتراضي: Depth، أو Depth N عند وجود عدة سلاسل بيانات.",
  "Name of this row in the diagram legend. Leave blank to use the caption of its track, or else its query in words.": "اسم هذا الصف في وسيلة إيضاح المخطط. يمكنك ترك الحقل فارغاً لاستخدام التسمية التوضيحية لمساره، أو الوصف النصي لاستعلامه إذا لم تكن للمسار تسمية توضيحية.",
