  "No nucleotide sequence available.": "لا يتوفر تسلسل نيوكليوتيدات.",
  "No pair has a BLAST TSV yet, so Generate draws no comparison. Choose a file for a pair under Selected pairs.": "لم يتم تعيين ملف BLAST TSV لأي زوج بعد، لذا لا يتم رسم أي مقارنة عند الإنشاء. يُرجى اختيار ملف لزوج ضمن القسم \"الأزواج المحددة\".",
  "No qualifiers available.": "لا يتوفر أي qualifier.",
  "No record ID matches the search.": "لا يوجد معرّف سجل يطابق البحث.",
  "No record has a feature that this selector names. Check the key and the value, for example {example}.": "لا يحتوي أي سجل على عنصر يشير إليه هذا المحدد. يُرجى التحقق من المفتاح والقيمة، مثل {example}.",
  "No record in the current input matches the record selector '{selector}'.": "لا يوجد سجل في المدخلات الحالية يطابق محدد السجل \"{selector}\".",
  "No record is reversed yet. Choose a direction in each card.": "لم يتم عكس أي سجل بعد. يُرجى اختيار اتجاه في كل بطاقة.",
  "No record is reversed.": "لم يتم عكس أي سجل.",
  "No record pair to compare. Records on the same Linear row are not compared: give each record its own row under Advanced comparison and layout (Record Layout), or add a sequence.": "لا يوجد زوج من السجلات للمقارنة. لا تتم مقارنة السجلات الموجودة في الصف نفسه من المخطط الخطي: يُرجى تخصيص صف لكل سجل ضمن القسم \"خيارات متقدمة للمقارنة والتخطيط\" (\"تخطيط السجلات\")، أو إضافة تسلسل.",
