  "No successful Result is available yet. Correct the cause and retry.": "لا توجد نتيجة ناجحة متوفرة بعد. يُرجى تصحيح السبب وإعادة المحاولة.",
  "No usable candidate": "لا يوجد مرشح قابل للاستخدام",
