  "No window found. The thresholds removed {count} alignments.": {"zero": "لم يتم العثور على أي نافذة. أزالت العتبات {count} عملية محاذاة.", "two": "لم يتم العثور على أي نافذة. أزالت العتبات {count} عملية محاذاة.", "few": "لم يتم العثور على أي نافذة. أزالت العتبات {count} عمليات محاذاة.", "many": "لم يتم العثور على أي نافذة. أزالت العتبات {count} عملية محاذاة.", "other": "لم يتم العثور على أي نافذة. أزالت العتبات {count} عملية محاذاة."},
