  "Not applied: label text, label visibility, or feature visibility changed while the table loaded. The changes were kept. Load the table again.": "لم يتم التطبيق: تغير نص التسمية أو رؤية التسمية أو رؤية العنصر أثناء تحميل الجدول. تم الاحتفاظ بالتغييرات. يُرجى تحميل الجدول مرة أخرى.",
  "Not applied: the displayed diagram changed while the table loaded. Load the table again.": "لم يتم التطبيق: تغير المخطط المعروض أثناء تحميل الجدول. يُرجى تحميل الجدول مرة أخرى.",
  "Not applied: {inputs} changed while the table loaded. Load the table again.": "لم يتم التطبيق: تغيرت المدخلات التالية أثناء تحميل الجدول: {inputs}. يُرجى تحميل الجدول مرة أخرى.",
  "Not applied; the existing label edits were kept.": "لم يتم التطبيق؛ تم الاحتفاظ بتعديلات التسميات الحالية.",
  "Not attached": "غير مرتبط",
  "Not available: the latest Align did not change any record direction.": "غير متوفر: لم تغير آخر عملية \"محاذاة\" أي اتجاه للسجلات.",
  "Not available: this Session does not record which directions the latest Align changed.": "غير متوفر: لا تسجل هذه الجلسة الاتجاهات التي غيرتها آخر عملية \"محاذاة\".",
