  "ON aligns Linear definitions in a common left column. OFF centers them in a common column width and follows row offsets, including center or similarity alignment.": "عند التشغيل، تتم محاذاة تعريفات المخطط الخطي في عمود أيسر مشترك. وعند الإيقاف، تتم محاذاتها إلى الوسط ضمن عرض عمود مشترك وتتبع إزاحات الصفوف، بما في ذلك المحاذاة إلى الوسط أو حسب التشابه.",
  "Off": "إيقاف",
  "Off (always hide)": "إيقاف (إخفاء دائماً)",
  "Off (hide; leave out of protein search)": "إيقاف (إخفاء واستبعاد من بحث البروتينات)",
