  "Offset must be a whole number of base pairs within the supported range.": "يجب أن تكون الإزاحة عدداً صحيحاً من أزواج القواعد ضمن المدى المدعوم.",
  "Older undo history and the redo history were discarded to stay within the history limit.": "تم حذف محفوظات التراجع الأقدم ومحفوظات الإعادة للبقاء ضمن حد المحفوظات.",
