  "One color per query": "لون واحد لكل query",
  "One or more saved target anchors are no longer usable. Select or Skip each target.": "لم تعد مرساة واحدة أو أكثر من مراسي الأهداف المحفوظة قابلة للاستخدام. يُرجى استخدام الخيار \"تحديد\" أو الخيار \"تخطي\" لكل هدف.",
  "One row (auto)": "صف واحد (تلقائي)",
  "One rule for only this feature.": "قاعدة واحدة لهذا العنصر فقط.",
  "One rule per current similarity-group member.": "قاعدة واحدة لكل عضو حالي في مجموعة التشابه.",
  "Only Features and Annotations rows can use On axis.": "يمكن استخدام الموضع \"على المحور\" في صفوف العناصر والتعليقات التوضيحية فقط.",
  "Only one enabled Features row is allowed.": "يُسمح بصف عناصر ممكّن واحد فقط.",
  "Only show labels matching case-insensitive Python regex. Examples: {first} and {second}. Use {exact} for exact matches.": "إظهار التسميات التي تطابق تعبيراً عادياً في Python فقط، دون التمييز بين الأحرف الكبيرة والصغيرة. أمثلة: {first} و {second}. ويمكن استخدام {exact} للمطابقة التامة.",
