  "Open the feature's popup and set Label visibility to Default, or change the setting that prevents its label.": "يُرجى فتح النافذة المنبثقة للعنصر وضبط الإعداد \"رؤية التسمية\" على \"افتراضي\"، أو تغيير الإعداد الذي يمنع ظهور تسميته.",
  "Open the first selected feature": "فتح أول عنصر محدد",
  "Open {label}": "فتح {label}",
