  "Operation error": "خطأ في العملية",
  "Optional circular plot title used when the title position is Top or Bottom. Leave blank to use the default species + strain title.": "عنوان اختياري للمخطط الدائري يُستخدم عندما يكون موضع العنوان هو الخيار \"أعلى\" أو الخيار \"أسفل\". يمكنك ترك الحقل فارغاً لاستخدام العنوان الافتراضي (النوع + السلالة).",
  "Optional fallback names for rings, one per source. Use new lines or commas.": "أسماء احتياطية اختيارية للحلقات، اسم واحد لكل مصدر. يمكنك الفصل بينها بأسطر جديدة أو بفواصل.",
