  "Overflow behavior": "سلوك التجاوز",
  "Overlapping feature parts cannot be traversed safely.": "لا يمكن اجتياز أجزاء العنصر المتداخلة بأمان.",
  "Overlapping genomic features are assigned to additional lanes; other tracks are repacked automatically.": "يتم تعيين العناصر الجينومية المتداخلة إلى مسارات فرعية إضافية، وتتم إعادة توزيع المسارات الأخرى تلقائياً.",
  "Overlay anchor": "تراكب على المرساة",
  "Override the center-label reserved radius in px. Lower values let inside tracks move closer to the center, where they may overlap the label.": "تجاوز نصف القطر المحجوز للتسمية المركزية بوحدة px. تسمح القيم الأقل للمسارات الداخلية بالاقتراب من المركز، حيث قد تتداخل مع التسمية.",
  "Overrides the inferred organism line for this Circular record. Leave empty to keep inference.": "يتجاوز سطر الكائن الحي المستنتج لسجل المخطط الدائري هذا. يمكنك ترك الحقل فارغاً للإبقاء على الاستنتاج.",
  "Overrides the inferred strain line for this Circular record. Leave empty to keep inference.": "يتجاوز سطر السلالة المستنتج لسجل المخطط الدائري هذا. يمكنك ترك الحقل فارغاً للإبقاء على الاستنتاج.",
  "PDF export error": "خطأ في تصدير PDF",
  "PDF fonts cannot represent this text. Use SVG to retain this text.": "تعذر تمثيل هذا النص بخطوط PDF. يُرجى استخدام SVG للاحتفاظ بهذا النص.",
  "PDF is limited to {limit} pt per side, and this figure is {width} x {height} pt.": "الحد الأقصى لكل جانب في تنسيق PDF هو {limit} pt، وأبعاد هذا الشكل: العرض {width} pt والارتفاع {height} pt.",
  "PNG export error": "خطأ في تصدير PNG",
  "PNG is limited to {limit} px per side, and this figure is {width} x {height} px.": "الحد الأقصى لكل جانب في تنسيق PNG هو {limit} px، وأبعاد هذا الشكل: العرض {width} px والارتفاع {height} px.",
  "PRESET SCHEMES": "الأنظمة المعدة مسبقاً",
  "Padding around annotation marks in pixels. Default: 2.": "الهامش حول علامات التعليقات التوضيحية بالبكسل. الافتراضي: 2.",
  "Padding must be a nonnegative finite number.": "يجب أن يكون الهامش عدداً محدوداً غير سالب.",
  "Paints the PNG background white. Turned off, the PNG keeps the transparent background of the drawing. SVG and PDF downloads have no background either way.": "يؤدي تشغيل هذا الخيار إلى رسم خلفية صورة PNG باللون الأبيض. وعند الإيقاف تحتفظ صورة PNG بالخلفية الشفافة للرسم. ولا تتضمن ملفات SVG و PDF التي يتم تنزيلها خلفية في الحالتين.",
  "Pair {pairs} is set to Upload BLAST TSV, so not every pair runs LOSAT.": "تم ضبط الزوج {pairs} على الخيار \"تحميل ملف BLAST TSV\"، لذا لا يتم تشغيل LOSAT لكل زوج.",
  "Pair: #{query} to #{subject}.": "الزوج: من #{query} إلى #{subject}.",
  "Pairs between rows {upper} and {lower}": "الأزواج بين الصف {upper} والصف {lower}",
  "Pairs {pairs} are set to Upload BLAST TSV, so not every pair runs LOSAT.": {"zero": "تم ضبط الأزواج {pairs} على الخيار \"تحميل ملف BLAST TSV\"، لذا لا يتم تشغيل LOSAT لكل زوج.", "two": "تم ضبط الزوجين {pairs} على الخيار \"تحميل ملف BLAST TSV\"، لذا لا يتم تشغيل LOSAT لكل زوج.", "few": "تم ضبط الأزواج {pairs} على الخيار \"تحميل ملف BLAST TSV\"، لذا لا يتم تشغيل LOSAT لكل زوج.", "many": "تم ضبط الأزواج {pairs} على الخيار \"تحميل ملف BLAST TSV\"، لذا لا يتم تشغيل LOSAT لكل زوج.", "other": "تم ضبط الأزواج {pairs} على الخيار \"تحميل ملف BLAST TSV\"، لذا لا يتم تشغيل LOSAT لكل زوج."},
