  "Palette: the palette \"{label}\" ({path}) waits to be applied, but Instant Preview is on, which applies a palette at once; it was dropped.": "لوحة الألوان: لوحة الألوان \"{label}\" ({path}) في انتظار التطبيق، لكن الخيار \"المعاينة الفورية للوحة الألوان\" قيد التشغيل ويطبق لوحة الألوان فوراً؛ لذا تمت إزالة لوحة الألوان المعلقة.",
