  "Per-feature Feature visibility, Label visibility, and label text edits of this diagram's records, in the {option} format of the CLI and Python API. Load replaces those edits; rows whose record or feature is not in this diagram are counted and not applied.": "تعديلات الإعدادين \"رؤية العنصر\" و\"رؤية التسمية\" ونص التسمية لكل عنصر في سجلات هذا المخطط، بتنسيق {option} في CLI وواجهة Python البرمجية. ويؤدي الأمر \"تحميل\" إلى استبدال هذه التعديلات؛ أما الصفوف التي لا يوجد سجلها أو عنصرها في هذا المخطط فيتم احتسابها ولا يتم تطبيقها.",
