  "Performance": "الأداء",
  "Physical radial gap on the side closer to the center, in pixels (px optional; nonnegative). Leave blank for auto.": "الفجوة الفعلية باتجاه نصف القطر في الجانب الأقرب إلى المركز، بالبكسل (الوحدة px اختيارية؛ قيمة غير سالبة). يمكنك ترك الحقل فارغاً لاستخدام القيمة التلقائية.",
  "Physical radial gap on the side farther from the center, in pixels (px optional; nonnegative). Leave blank for auto.": "الفجوة الفعلية باتجاه نصف القطر في الجانب الأبعد عن المركز، بالبكسل (الوحدة px اختيارية؛ قيمة غير سالبة). يمكنك ترك الحقل فارغاً لاستخدام القيمة التلقائية.",
  "Pick a row to go back or forward to it": "يُرجى اختيار صف للرجوع إلى تلك الحالة أو التقدم إليها.",
  "Place a value before the repetition operator.": "يُرجى وضع قيمة قبل عامل التكرار.",
  "Place global flags at the start of the pattern.": "يُرجى وضع global flags في بداية النمط.",
