  "Similarity-group member product": "ناتج عضو مجموعة التشابه",
  "Similarity-group member protein ID": "معرّف بروتين عضو مجموعة التشابه",
  "Simple mode only. Above places features above the axis, Features on axis centers them on it, and Below places them below it. Use Reset to copy this choice into the custom stack.": "هذا الإعداد خاص بالوضع البسيط فقط. يضع الخيار \"فوق\" العناصر فوق المحور، ويجعل الخيار \"العناصر على المحور\" مراكز العناصر على المحور، ويضعها الخيار \"تحت\" أسفله. يمكنك استخدام الزر \"إعادة تعيين\" لنسخ هذا الاختيار إلى المكدس المخصص.",
  "Simple mode only. Display a GC content track; use Reset to copy it into the custom stack.": "خاص بالوضع البسيط فقط. عرض مسار محتوى GC؛ ويمكنك استخدام الزر \"إعادة تعيين\" لنسخه إلى المكدس المخصص.",
  "Simple mode only. Display a GC skew track; use Reset to copy it into the custom stack.": "خاص بالوضع البسيط فقط. عرض مسار GC skew؛ ويمكنك استخدام الزر \"إعادة تعيين\" لنسخه إلى المكدس المخصص.",
  "Simple mode only. Display depth coverage tracks from uploaded TSV files; use Reset to copy them into the custom stack.": "خاص بالوضع البسيط فقط. عرض مسارات عمق التغطية من ملفات TSV المحمّلة؛ ويمكنك استخدام الزر \"إعادة تعيين\" لنسخها إلى المكدس المخصص.",
  "Simple mode only. Use Reset to rebuild the custom stack from this setting.": "خاص بالوضع البسيط فقط. يمكنك استخدام الزر \"إعادة تعيين\" لإعادة بناء المكدس المخصص من هذا الإعداد.",
  "Single-record crop, orientation and titles": "اقتصاص سجل واحد واتجاهه وعناوينه",
  "Size": "الحجم",
  "Size of the color boxes in the legend.": "حجم مربعات الألوان في وسيلة الإيضاح.",
