  "Skipped {count} annotation rows.": {"zero": "تم تخطي {count} صف من التعليقات التوضيحية.", "two": "تم تخطي {count} صف من التعليقات التوضيحية.", "few": "تم تخطي {count} صفوف من التعليقات التوضيحية.", "many": "تم تخطي {count} صفاً من التعليقات التوضيحية.", "other": "تم تخطي {count} صف من التعليقات التوضيحية."},
  "Slot id": "معرّف الخانة",
  "Small Tick": "علامة تجزئة صغيرة",
  "Small tick interval in x coverage units. Leave blank to hide small ticks.": "الفاصل بين علامات التجزئة الصغيرة بوحدات التغطية x. يؤدي ترك الحقل فارغاً إلى إخفاء علامات التجزئة الصغيرة.",
  "Some browser virtual paths could not be mapped to visible file names, so this command is only an approximation.": "تعذر ربط بعض مسارات الملفات الافتراضية في المتصفح بأسماء ملفات ظاهرة، لذا فإن هذا الأمر تقريبي فقط.",
  "Some parts of this file cannot be fully restored:": "لا يمكن استعادة بعض أجزاء هذا الملف بالكامل:",
  "Some records use different files or have no depth track. Choosing a file applies it to every record in this File.": "تستخدم بعض السجلات ملفات مختلفة أو لا يوجد لها مسار عمق. يؤدي اختيار ملف إلى تطبيقه على كل سجل في بطاقة الملف هذه.",
