  "Step": "الخطوة",
  "Step (bp)": "الخطوة (bp)",
  "Step size for GC content/skew. Default: 100 bp (<1 Mb), 1 kb (<10 Mb), 10 kb (<100 Mb), 100 kb (>=100 Mb), and at most a tenth of the Auto window.": "حجم الخطوة لحساب محتوى GC و GC skew. القيمة الافتراضية: 100 bp (للأطوال الأقل من 1 Mb)، و 1 kb (للأقل من 10 Mb)، و 10 kb (للأقل من 100 Mb)، و 100 kb (للأطوال البالغة 100 Mb أو أكثر)، وبحد أقصى 10% من النافذة التلقائية.",
  "Step size for depth aggregation. Blank: a tenth of the GC step, at least 1 bp.": "حجم الخطوة لتجميع العمق. عند ترك الحقل فارغاً: 10% من خطوة GC بحد أدنى 1 bp.",
  "Str.": "السلسلة",
  "Strain": "السلالة",
  "Strain or isolate name used in the circular center label.": "اسم السلالة أو العزلة المستخدم في التسمية المركزية للمخطط الدائري.",
  "Strand": "السلسلة",
  "Strand: neighboring anchors of a block follow its strand orientation and the gene order. Gene order: they follow the gene order only.": "الخيار \"السلسلة\": تتبع المراسي المتجاورة في الكتلة اتجاه سلسلتها وترتيب الجينات. الخيار \"ترتيب الجينات\": تتبع ترتيب الجينات فقط.",
  "Stretch the overlay from its anchor to this slot, over every slot between them (to_slot). None: the overlay's own band.": "تمديد التراكب من مرساته حتى هذه الخانة، فوق كل خانة بينهما (to_slot). الخيار \"بلا\": نطاق التراكب نفسه.",
  "Stroke": "الحد",
