  "location and record_location rows cannot be matched to {count} labels on cropped, reverse-complemented, or rotated records until the diagram records where it drew them. Generate the diagram again, then load the table.": {"zero": "لا يمكن مطابقة صفوف location و record_location مع {count} تسمية على سجلات تم اقتصاصها أو تحويلها إلى المكمل العكسي أو تدويرها إلى أن يسجل المخطط مكان رسمها. يُرجى إعادة إنشاء المخطط ثم تحميل الجدول.", "two": "لا يمكن مطابقة صفوف location و record_location مع {count} تسمية على سجلات تم اقتصاصها أو تحويلها إلى المكمل العكسي أو تدويرها إلى أن يسجل المخطط مكان رسمها. يُرجى إعادة إنشاء المخطط ثم تحميل الجدول.", "few": "لا يمكن مطابقة صفوف location و record_location مع {count} تسميات على سجلات تم اقتصاصها أو تحويلها إلى المكمل العكسي أو تدويرها إلى أن يسجل المخطط مكان رسمها. يُرجى إعادة إنشاء المخطط ثم تحميل الجدول.", "many": "لا يمكن مطابقة صفوف location و record_location مع {count} تسمية على سجلات تم اقتصاصها أو تحويلها إلى المكمل العكسي أو تدويرها إلى أن يسجل المخطط مكان رسمها. يُرجى إعادة إنشاء المخطط ثم تحميل الجدول.", "other": "لا يمكن مطابقة صفوف location و record_location مع {count} تسمية على سجلات تم اقتصاصها أو تحويلها إلى المكمل العكسي أو تدويرها إلى أن يسجل المخطط مكان رسمها. يُرجى إعادة إنشاء المخطط ثم تحميل الجدول."},
  "megablast is fastest for highly similar nucleotide sequences; blastn is more sensitive.": "يكون megablast الأسرع مع تسلسلات النيوكليوتيدات شديدة التشابه، بينما يكون blastn أكثر حساسية.",
