  "{complete} found in full, {partial} in part, {absent} not at all.": "جينات تم العثور عليها بالكامل: {complete}، وجزئياً: {partial}، ولم يتم العثور عليها: {absent}.",
  "{confidence} confidence": "ثقة {confidence}",
  "{count} Feature visibility edit from an older Session hid every feature with the same hash, such as each copy of a duplicated record. It now applies only to the feature that was edited, so the next Generate draws the others.": "أخفى {count} تعديل لرؤية العنصر من جلسة أقدم كل عنصر له قيمة التجزئة نفسها، مثل كل نسخة من سجل مكرر. يسري هذا التعديل الآن على العنصر الذي تم تعديله فقط، لذا سيتم رسم العناصر الأخرى عند الإنشاء التالي.",
  "{count} Feature visibility edits from an older Session hid every feature with the same hash, such as each copy of a duplicated record. Each now applies only to the feature that was edited, so the next Generate draws the others.": {"zero": "أخفى {count} تعديل لرؤية العنصر من جلسة أقدم كل عنصر له قيمة التجزئة نفسها، مثل كل نسخة من سجل مكرر. يسري كل تعديل الآن على العنصر الذي تم تعديله فقط، لذا سيتم رسم العناصر الأخرى عند الإنشاء التالي.", "two": "أخفى {count} تعديل لرؤية العنصر من جلسة أقدم كل عنصر له قيمة التجزئة نفسها، مثل كل نسخة من سجل مكرر. يسري كل تعديل الآن على العنصر الذي تم تعديله فقط، لذا سيتم رسم العناصر الأخرى عند الإنشاء التالي.", "few": "أخفت {count} تعديلات لرؤية العنصر من جلسة أقدم كل عنصر له قيمة التجزئة نفسها، مثل كل نسخة من سجل مكرر. يسري كل تعديل الآن على العنصر الذي تم تعديله فقط، لذا سيتم رسم العناصر الأخرى عند الإنشاء التالي.", "many": "أخفى {count} تعديلاً لرؤية العنصر من جلسة أقدم كل عنصر له قيمة التجزئة نفسها، مثل كل نسخة من سجل مكرر. يسري كل تعديل الآن على العنصر الذي تم تعديله فقط، لذا سيتم رسم العناصر الأخرى عند الإنشاء التالي.", "other": "أخفى {count} تعديل لرؤية العنصر من جلسة أقدم كل عنصر له قيمة التجزئة نفسها، مثل كل نسخة من سجل مكرر. يسري كل تعديل الآن على العنصر الذي تم تعديله فقط، لذا سيتم رسم العناصر الأخرى عند الإنشاء التالي."},
  "{count} TSV": "{count} ملف TSV",
