  "{count} adjacent pair": "{count} زوج متجاور",
  "{count} adjacent pairs": {"zero": "{count} زوج متجاور", "two": "{count} زوج متجاور", "few": "{count} أزواج متجاورة", "many": "{count} زوجاً متجاوراً", "other": "{count} زوج متجاور"},
  "{count} aligned": "تمت المحاذاة: {count}",
  "{count} annotation from an older Session named a feature by {selector}. It now names that feature by its source, so it stays on the feature when the crop or orientation changes.": "كان {count} تعليق توضيحي من جلسة أقدم يشير إلى عنصر بواسطة {selector}. وهو يشير الآن إلى ذلك العنصر بواسطة مصدره، لذا يبقى على العنصر عند تغيير الاقتصاص أو الاتجاه.",
  "{count} annotation of a selected feature that the current diagram does not draw was not exported.": "لم يتم تصدير {count} تعليق توضيحي لعنصر محدد لا يرسمه المخطط الحالي.",
  "{count} annotation of a selected feature was written as {recordSelector} and {featureSelector}. It names the same feature only while the record order stays as drawn.": "تمت كتابة {count} تعليق توضيحي لعنصر محدد بالصيغة {recordSelector} و {featureSelector}. وهو يشير إلى العنصر نفسه فقط ما دام ترتيب السجلات كما هو مرسوم.",
  "{count} annotations from an older Session named a feature by {selector}. Each now names that feature by its source, so it stays on the feature when the crop or orientation changes.": {"zero": "كان {count} تعليق توضيحي من جلسة أقدم يشير إلى عنصر بواسطة {selector}. ويشير كل منها الآن إلى عنصره بواسطة مصدره، لذا يبقى على العنصر عند تغيير الاقتصاص أو الاتجاه.", "two": "كان {count} تعليق توضيحي من جلسة أقدم يشير إلى عنصر بواسطة {selector}. ويشير كل منها الآن إلى عنصره بواسطة مصدره، لذا يبقى على العنصر عند تغيير الاقتصاص أو الاتجاه.", "few": "كانت {count} تعليقات توضيحية من جلسة أقدم تشير إلى عنصر بواسطة {selector}. ويشير كل منها الآن إلى عنصره بواسطة مصدره، لذا يبقى على العنصر عند تغيير الاقتصاص أو الاتجاه.", "many": "كان {count} تعليقاً توضيحياً من جلسة أقدم يشير إلى عنصر بواسطة {selector}. ويشير كل منها الآن إلى عنصره بواسطة مصدره، لذا يبقى على العنصر عند تغيير الاقتصاص أو الاتجاه.", "other": "كان {count} تعليق توضيحي من جلسة أقدم يشير إلى عنصر بواسطة {selector}. ويشير كل منها الآن إلى عنصره بواسطة مصدره، لذا يبقى على العنصر عند تغيير الاقتصاص أو الاتجاه."},
  "{count} annotations of selected features that the current diagram does not draw were not exported.": {"zero": "لم يتم تصدير {count} تعليق توضيحي لعناصر محددة لا يرسمها المخطط الحالي.", "two": "لم يتم تصدير {count} تعليق توضيحي لعناصر محددة لا يرسمها المخطط الحالي.", "few": "لم يتم تصدير {count} تعليقات توضيحية لعناصر محددة لا يرسمها المخطط الحالي.", "many": "لم يتم تصدير {count} تعليقاً توضيحياً لعناصر محددة لا يرسمها المخطط الحالي.", "other": "لم يتم تصدير {count} تعليق توضيحي لعناصر محددة لا يرسمها المخطط الحالي."},
  "{count} annotations of selected features were written as {recordSelector} and {featureSelector}. They name the same features only while the record order stays as drawn.": {"zero": "تمت كتابة {count} تعليق توضيحي لعناصر محددة بالصيغة {recordSelector} و {featureSelector}. وتشير هذه التعليقات التوضيحية إلى العناصر نفسها فقط ما دام ترتيب السجلات كما هو مرسوم.", "two": "تمت كتابة {count} تعليق توضيحي لعناصر محددة بالصيغة {recordSelector} و {featureSelector}. وتشير هذه التعليقات التوضيحية إلى العناصر نفسها فقط ما دام ترتيب السجلات كما هو مرسوم.", "few": "تمت كتابة {count} تعليقات توضيحية لعناصر محددة بالصيغة {recordSelector} و {featureSelector}. وتشير هذه التعليقات التوضيحية إلى العناصر نفسها فقط ما دام ترتيب السجلات كما هو مرسوم.", "many": "تمت كتابة {count} تعليقاً توضيحياً لعناصر محددة بالصيغة {recordSelector} و {featureSelector}. وتشير هذه التعليقات التوضيحية إلى العناصر نفسها فقط ما دام ترتيب السجلات كما هو مرسوم.", "other": "تمت كتابة {count} تعليق توضيحي لعناصر محددة بالصيغة {recordSelector} و {featureSelector}. وتشير هذه التعليقات التوضيحية إلى العناصر نفسها فقط ما دام ترتيب السجلات كما هو مرسوم."},
