  "{count} feature edits apply to features outside the current crop or display; they apply again when those features are drawn.": {"zero": "يسري {count} تعديل لعنصر على عناصر خارج الاقتصاص أو العرض الحالي؛ ويسري من جديد عند رسم هذه العناصر.", "two": "يسري {count} تعديل لعنصر على عناصر خارج الاقتصاص أو العرض الحالي؛ ويسري من جديد عند رسم هذه العناصر.", "few": "تسري {count} تعديلات لعناصر على عناصر خارج الاقتصاص أو العرض الحالي؛ وتسري من جديد عند رسم هذه العناصر.", "many": "يسري {count} تعديلاً لعنصر على عناصر خارج الاقتصاص أو العرض الحالي؛ ويسري من جديد عند رسم هذه العناصر.", "other": "يسري {count} تعديل لعنصر على عناصر خارج الاقتصاص أو العرض الحالي؛ ويسري من جديد عند رسم هذه العناصر."},
