  "{count} {selector} value from an older Session could not be renamed to the hash of a feature in its source record: the saved diagram drew a cropped or reverse-complemented record, and the value names features of several source hashes there, or the sources were not read again. {selector} now names a feature by its hash in the source record, so the value may now match another feature or none.": "تعذرت إعادة تسمية {count} قيمة للمعلمة {selector} من جلسة أقدم إلى قيمة التجزئة لعنصر في سجله المصدر: فقد رسم المخطط المحفوظ سجلاً تم اقتصاصه أو تحويله إلى المكمل العكسي، وتشير القيمة هناك إلى عناصر لها قيم تجزئة مختلفة في المصدر، أو لم تتم قراءة المصادر مجدداً. تشير المعلمة {selector} الآن إلى العنصر بقيمة التجزئة الخاصة به في السجل المصدر، لذا قد تطابق القيمة الآن عنصراً آخر أو لا تطابق أي عنصر.",
  "{count} {selector} values from an older Session could not be renamed to the hash of a feature in its source record: the saved diagram drew a cropped or reverse-complemented record, and the value names features of several source hashes there, or the sources were not read again. {selector} now names a feature by its hash in the source record, so each may now match another feature or none.": {"zero": "تعذرت إعادة تسمية {count} قيمة للمعلمة {selector} من جلسة أقدم إلى قيمة التجزئة لعنصر في سجله المصدر: فقد رسم المخطط المحفوظ سجلاً تم اقتصاصه أو تحويله إلى المكمل العكسي، وتشير القيمة هناك إلى عناصر لها قيم تجزئة مختلفة في المصدر، أو لم تتم قراءة المصادر مجدداً. تشير المعلمة {selector} الآن إلى العنصر بقيمة التجزئة الخاصة به في السجل المصدر، لذا قد تطابق كل قيمة الآن عنصراً آخر أو لا تطابق أي عنصر.", "two": "تعذرت إعادة تسمية {count} قيمة للمعلمة {selector} من جلسة أقدم إلى قيمة التجزئة لعنصر في سجله المصدر: فقد رسم المخطط المحفوظ سجلاً تم اقتصاصه أو تحويله إلى المكمل العكسي، وتشير القيمة هناك إلى عناصر لها قيم تجزئة مختلفة في المصدر، أو لم تتم قراءة المصادر مجدداً. تشير المعلمة {selector} الآن إلى العنصر بقيمة التجزئة الخاصة به في السجل المصدر، لذا قد تطابق كل قيمة الآن عنصراً آخر أو لا تطابق أي عنصر.", "few": "تعذرت إعادة تسمية {count} قيم للمعلمة {selector} من جلسة أقدم إلى قيمة التجزئة لعنصر في سجله المصدر: فقد رسم المخطط المحفوظ سجلاً تم اقتصاصه أو تحويله إلى المكمل العكسي، وتشير القيم هناك إلى عناصر لها قيم تجزئة مختلفة في المصدر، أو لم تتم قراءة المصادر مجدداً. تشير المعلمة {selector} الآن إلى العنصر بقيمة التجزئة الخاصة به في السجل المصدر، لذا قد تطابق كل قيمة الآن عنصراً آخر أو لا تطابق أي عنصر.", "many": "تعذرت إعادة تسمية {count} قيمة للمعلمة {selector} من جلسة أقدم إلى قيمة التجزئة لعنصر في سجله المصدر: فقد رسم المخطط المحفوظ سجلاً تم اقتصاصه أو تحويله إلى المكمل العكسي، وتشير القيمة هناك إلى عناصر لها قيم تجزئة مختلفة في المصدر، أو لم تتم قراءة المصادر مجدداً. تشير المعلمة {selector} الآن إلى العنصر بقيمة التجزئة الخاصة به في السجل المصدر، لذا قد تطابق كل قيمة الآن عنصراً آخر أو لا تطابق أي عنصر.", "other": "تعذرت إعادة تسمية {count} قيمة للمعلمة {selector} من جلسة أقدم إلى قيمة التجزئة لعنصر في سجله المصدر: فقد رسم المخطط المحفوظ سجلاً تم اقتصاصه أو تحويله إلى المكمل العكسي، وتشير القيمة هناك إلى عناصر لها قيم تجزئة مختلفة في المصدر، أو لم تتم قراءة المصادر مجدداً. تشير المعلمة {selector} الآن إلى العنصر بقيمة التجزئة الخاصة به في السجل المصدر، لذا قد تطابق كل قيمة الآن عنصراً آخر أو لا تطابق أي عنصر."},
